body.script:
(function () {
    var self = document.currentScript;
    var banners = JSON.parse(self.getAttribute('data-banners') || '[]');
    var screen = document.getElementById('screen');
    var dots = document.getElementById('dots');
    var zPrev = document.getElementById('zPrev');
    var zNext = document.getElementById('zNext');
    var zPause = document.getElementById('zPause');
    var pauseIc = document.querySelector('.ic-pause');
    var playIc = document.querySelector('.ic-play');
    if (!banners.length) {
        var e = document.createElement('div');
        e.className = 'empty';
        e.textContent = 'No live banners yet. Add one under Banners.';
        screen.appendChild(e);
        zPrev.style.display = 'none'; zNext.style.display = 'none'; zPause.style.display = 'none';
        return;
    }
    var slides = [];
    banners.forEach(function (b, i) {
        var s = document.createElement('div');
        s.className = 'slide' + (i === 0 ? ' active' : '');
        if (b.media_type === 'video' && b.video) {
            var v = document.createElement('video');
            v.src = b.video; v.muted = true; v.playsInline = true;
            var isAuto = !Number(b.scroll_seconds);
            v.loop = !isAuto;
            if (isAuto) {
                v.addEventListener('ended', function () {
                    if (!paused) go(1);
                });
            }
            s.appendChild(v);
        } else if (b.image) {
            var img = document.createElement('img');
            img.src = b.image;
            s.appendChild(img);
        }
        screen.insertBefore(s, screen.firstChild);
        slides.push({ el: s, b: b });
        var d = document.createElement('div');
        d.className = 'dot' + (i === 0 ? ' on' : '');
        dots.appendChild(d);
    });
    var idx = 0, paused = false, timer = null;
    function show(i) {
        slides.forEach(function (sl, j) {
            sl.el.classList.toggle('active', j === i);
            dots.children[j].classList.toggle('on', j === i);
            var v = sl.el.querySelector('video');
            if (v) { if (j === i && !paused) { try { v.currentTime = 0; } catch (e) {} v.play().catch(function () {}); } else { v.pause(); } }
        });
    }
    function schedule() {
        clearTimeout(timer);
        if (paused || slides.length === 1) return;
        var cur = slides[idx].b;
        // Video on Auto advances when it ends (see 'ended' listener), not on a timer.
        if (cur.media_type === 'video' && !Number(cur.scroll_seconds)) return;
        var secs = Number(cur.scroll_seconds) || 6;
        timer = setTimeout(function () { go(1); }, Math.max(2, secs) * 1000);
    }
    function go(dir) {
        idx = (idx + dir + slides.length) % slides.length;
        show(idx);
        schedule();
    }
    zPrev.addEventListener('click', function () { go(-1); });
    zNext.addEventListener('click', function () { go(1); });
    zPause.addEventListener('click', function () {
        paused = !paused;
        pauseIc.style.display = paused ? 'none' : '';
        playIc.style.display = paused ? '' : 'none';
        if (paused) {
            clearTimeout(timer);
            var v = slides[idx].el.querySelector('video');
            if (v) v.pause();
        } else {
            show(idx);
            schedule();
        }
    });
    show(0);
    schedule();
})();
